import{R as a,e as i,f as s,U as d}from"./chunks/framework.ywem4qy5.js";const t="/assets/synced-field.BZf7EgyF.png",u=JSON.parse('{"title":"Synced Fields","description":"","frontmatter":{},"headers":[],"relativePath":"forms/synced-fields.md","filePath":"forms/synced-fields.md","lastUpdated":1776231488000}'),n={name:"forms/synced-fields.md"};function l(o,e,r,c,h,f){return i(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="synced-fields" tabindex="-1">Synced Fields <a class="header-anchor" href="#synced-fields" aria-label="Permalink to &quot;Synced Fields&quot;">​</a></h1><p>Synced fields let you reuse the same field definition across multiple forms.</p><p>They are useful when a field should stay consistent everywhere it appears, instead of becoming a separate copy in each form. When a field is added as a synced field, Formie links it to the original field, so changes made to one instance are reflected everywhere that synced field is used.</p><p>This is especially useful for fields that appear repeatedly across a site, such as email addresses, phone numbers, consent checkboxes, and other common contact details.</p><h2 id="when-to-use-synced-fields" tabindex="-1">When to use synced fields <a class="header-anchor" href="#when-to-use-synced-fields" aria-label="Permalink to &quot;When to use synced fields&quot;">​</a></h2><p>Synced fields are a good fit when:</p><ul><li>the field should behave the same way in every form</li><li>you want one change to update every use of that field</li><li>you are trying to avoid duplicated maintenance</li></ul><p>They are a poor fit when a field only looks similar but needs to drift over time. In that case, a normal copied field is usually the better choice.</p><h2 id="adding-a-synced-field" tabindex="-1">Adding a synced field <a class="header-anchor" href="#adding-a-synced-field" aria-label="Permalink to &quot;Adding a synced field&quot;">​</a></h2><p>In the form builder, add a field from the existing fields picker instead of creating a new one. When you choose an existing field, you can add it as a synced field so it stays linked to the original.</p><p><img src="'+t+'" alt="Synced field badge in the builder"></p><p>That same picker can also add a normal copied field instead. The difference is important:</p><ul><li>a copied field starts as a duplicate, then becomes independent</li><li>a synced field stays linked</li></ul><p>Because the field stays linked, editing it in one form means editing it everywhere. That is what makes synced fields useful, but it is also why they need a little more care.</p><h2 id="working-with-shared-fields" tabindex="-1">Working with shared fields <a class="header-anchor" href="#working-with-shared-fields" aria-label="Permalink to &quot;Working with shared fields&quot;">​</a></h2><p>Formie warns you about this in the builder, but it is still worth being deliberate. If you need an independent version later, the usual answer is to create a new field rather than trying to keep changing a shared one.</p>',16)])])}const y=a(n,[["render",l]]);export{u as __pageData,y as default};
